"use client";

import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import axios from "axios";

type Employee = {
  id: number;
  name: string;
  email: string;
  phone?: string | null;
  department?: string | null;
  position?: string | null;
  salary?: number | string | null;
};

type EmployeeForm = Omit<Employee, "id">;

const API_URL = `${process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000/api"}/employees`;
const emptyForm: EmployeeForm = { name: "", email: "", phone: "", department: "", position: "", salary: "" };
const departments = ["Engineering", "Design", "Marketing", "Human Resources", "Finance", "Operations", "Sales"];
const colors = ["lavender", "peach", "mint", "blue", "rose", "gold"];

function initials(name: string) {
  return name.split(" ").filter(Boolean).slice(0, 2).map((part) => part[0]).join("").toUpperCase() || "?";
}

function currency(value?: number | string | null) {
  if (value === null || value === undefined || value === "") return "—";
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(Number(value));
}

export default function Home() {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [query, setQuery] = useState("");
  const [department, setDepartment] = useState("All departments");
  const [modal, setModal] = useState(false);
  const [editing, setEditing] = useState<Employee | null>(null);
  const [viewing, setViewing] = useState<Employee | null>(null);
  const [loadingDetails, setLoadingDetails] = useState(false);
  const [form, setForm] = useState<EmployeeForm>(emptyForm);
  const [saving, setSaving] = useState(false);
  const [notice, setNotice] = useState("");

  const loadEmployees = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const response = await axios.get<{ data: Employee[] }>(API_URL);
      setEmployees(response.data.data);
    } catch {
      setError("We couldn’t connect to the employee service. Check that the backend is running and try again.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void loadEmployees(); }, [loadEmployees]);

  const filtered = useMemo(() => employees.filter((employee) => {
    const matchesQuery = `${employee.name} ${employee.email} ${employee.position || ""} ${employee.department || ""}`.toLowerCase().includes(query.toLowerCase());
    return matchesQuery && (department === "All departments" || employee.department === department);
  }), [employees, query, department]);

  const openCreate = () => { setEditing(null); setForm(emptyForm); setModal(true); };
  const openEdit = (employee: Employee) => {
    setEditing(employee);
    setForm({ name: employee.name, email: employee.email, phone: employee.phone || "", department: employee.department || "", position: employee.position || "", salary: employee.salary ?? "" });
    setModal(true);
  };

  async function viewEmployee(employee: Employee) {
    setLoadingDetails(true);
    setViewing(employee);
    try {
      const response = await axios.get<{ data: Employee }>(`${API_URL}/${employee.id}`);
      setViewing(response.data.data);
    } catch {
      setError("Couldn’t load this employee’s details. Please try again.");
      setViewing(null);
    } finally { setLoadingDetails(false); }
  }

  async function submitEmployee(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSaving(true);
    setError("");
    const payload = { ...form, salary: form.salary === "" ? null : Number(form.salary) };
    try {
      if (editing) await axios.put(`${API_URL}/${editing.id}`, payload);
      else await axios.post(API_URL, payload);
      setModal(false);
      setNotice(editing ? "Employee details updated." : "Employee added to your team.");
      window.setTimeout(() => setNotice(""), 3200);
      await loadEmployees();
    } catch (err) {
      const message = axios.isAxiosError(err) ? err.response?.data?.message : "Please try again.";
      setError(message || "Unable to save employee. Please try again.");
    } finally { setSaving(false); }
  }

  async function deleteEmployee(employee: Employee) {
    if (!window.confirm(`Delete ${employee.name} from your team? This action cannot be undone.`)) return;
    try {
      await axios.delete(`${API_URL}/${employee.id}`);
      setEmployees((current) => current.filter((item) => item.id !== employee.id));
      setNotice(`${employee.name} was removed.`);
      window.setTimeout(() => setNotice(""), 3200);
    } catch {
      setError("Couldn’t delete this employee. Please try again.");
    }
  }

  const departmentCount = new Set(employees.map((employee) => employee.department).filter(Boolean)).size;
  const averageSalary = employees.length ? employees.reduce((sum, employee) => sum + Number(employee.salary || 0), 0) / employees.length : 0;

  return (
    <main className="app-shell">
      <aside className="sidebar">
        <a className="brand" href="#top" aria-label="Peopleboard home"><span className="brand-mark">p<span>.</span></span><span>peopleboard</span></a>
        <div className="workspace-label">WORKSPACE</div>
        <nav className="side-nav" aria-label="Main navigation">
          <a className="nav-item" href="#overview"><span className="nav-icon">◫</span> Overview</a>
          <a className="nav-item active" href="#employees"><span className="nav-icon">♙</span> Employees <span className="nav-count">{employees.length}</span></a>
          <a className="nav-item" href="#departments"><span className="nav-icon">▦</span> Departments</a>
          <a className="nav-item" href="#reports"><span className="nav-icon">⌁</span> Reports</a>
        </nav>
        <div className="sidebar-bottom">
          <div className="help-card"><div className="help-spark">✳</div><strong>Need a hand?</strong><p>Visit our help center to find answers and tips.</p><a href="mailto:support@example.com">Visit help center <span>↗</span></a></div>
          <button className="profile-button"><span className="profile-avatar">JD</span><span className="profile-copy"><strong>Jordan Davis</strong><small>Workspace admin</small></span><span className="profile-more">···</span></button>
        </div>
      </aside>

      <section className="main-area" id="top">
        <header className="topbar"><div className="breadcrumbs"><span>Workspace</span><span className="crumb-slash">/</span><strong>Employees</strong></div><div className="top-actions"><button className="icon-button" aria-label="Notifications">♧<i /></button><span className="top-divider" /><button className="top-user"><span className="profile-avatar small">JD</span><span>Jordan Davis</span><span className="chevron">⌄</span></button></div></header>
        <div className="content" id="employees">
          <div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-dot" /> PEOPLE DIRECTORY</div><h1>Your people, <em>at a glance.</em></h1><p className="subtitle">Manage your team and keep everyone’s details in one place.</p></div><button className="primary-button" onClick={openCreate}><span>＋</span> Add employee</button></div>

          {error && <div className="error-banner" role="alert"><span>!</span>{error}<button onClick={() => void loadEmployees()}>Retry</button></div>}
          {notice && <div className="notice-banner" role="status"><span>✓</span>{notice}</div>}

          <div className="stats-grid" id="overview">
            <article className="stat-card"><div className="stat-top"><span>Total employees</span><span className="stat-icon violet">♙</span></div><div className="stat-value">{loading ? "—" : employees.length.toString().padStart(2, "0")}</div><div className="stat-foot"><span className="stat-caption">Across your organization</span><span className="stat-trend">↗ Growing team</span></div></article>
            <article className="stat-card"><div className="stat-top"><span>Departments</span><span className="stat-icon peach-icon">▦</span></div><div className="stat-value">{loading ? "—" : departmentCount.toString().padStart(2, "0")}</div><div className="stat-foot"><span className="stat-caption">Teams working together</span><span className="stat-neutral">Active</span></div></article>
            <article className="stat-card"><div className="stat-top"><span>Average salary</span><span className="stat-icon mint-icon">＄</span></div><div className="stat-value salary-stat">{loading ? "—" : currency(averageSalary)}</div><div className="stat-foot"><span className="stat-caption">Annual compensation</span><span className="stat-neutral">Per employee</span></div></article>
          </div>

          <section className="directory-card">
            <div className="directory-heading"><div><h2>All employees <span className="table-count">{filtered.length}</span></h2><p>A complete list of everyone on your team.</p></div><button className="export-button" onClick={() => window.print()}><span>↓</span> Export</button></div>
            <div className="table-tools"><label className="search-box"><span>⌕</span><input aria-label="Search employees" placeholder="Search by name, role, or email..." value={query} onChange={(event) => setQuery(event.target.value)} /><kbd>⌘ K</kbd></label><label className="filter-select"><span>☷</span><select aria-label="Filter by department" value={department} onChange={(event) => setDepartment(event.target.value)}><option>All departments</option>{departments.map((item) => <option key={item}>{item}</option>)}</select><span className="select-chevron">⌄</span></label></div>
            <div className="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>DEPARTMENT</th><th>POSITION</th><th>ANNUAL SALARY</th><th className="actions-head">ACTIONS</th></tr></thead><tbody>
              {loading ? <tr><td colSpan={5}><div className="empty-state"><span className="spinner" />Loading your team...</div></td></tr> : filtered.length === 0 ? <tr><td colSpan={5}><div className="empty-state"><span className="empty-icon">♙</span><strong>{employees.length ? "No employees match your search" : "Your team starts here"}</strong><span>{employees.length ? "Try another name or department." : "Add your first employee to get started."}</span>{!employees.length && <button className="text-button" onClick={openCreate}>＋ Add your first employee</button>}</div></td></tr> : filtered.map((employee, index) => <tr key={employee.id}><td><div className="employee-cell"><span className={`employee-avatar ${colors[index % colors.length]}`}>{initials(employee.name)}</span><span className="employee-copy"><strong>{employee.name}</strong><small>{employee.email}</small></span></div></td><td><span className="department-tag">{employee.department || "Unassigned"}</span></td><td className="position-cell">{employee.position || "—"}</td><td className="salary-cell">{currency(employee.salary)}</td><td><div className="row-actions"><button aria-label={`View ${employee.name}`} title="View employee" onClick={() => void viewEmployee(employee)}>◉</button><button aria-label={`Edit ${employee.name}`} title="Edit employee" onClick={() => openEdit(employee)}>✎</button><button aria-label={`Delete ${employee.name}`} title="Delete employee" onClick={() => void deleteEmployee(employee)}>⌫</button></div></td></tr>)}
            </tbody></table></div>
            <footer className="table-footer"><span>Showing <strong>{filtered.length ? 1 : 0}–{filtered.length}</strong> of <strong>{employees.length}</strong> employees</span><div className="pagination"><button disabled aria-label="Previous page">‹</button><button className="page-current">1</button><button disabled aria-label="Next page">›</button></div></footer>
          </section>
          <footer className="page-footer"><span>© 2025 Peopleboard</span><span>Made for teams that care about people <span className="footer-heart">♥</span></span><a href="mailto:support@example.com">Help &amp; support ↗</a></footer>
        </div>
      </section>

      {viewing && <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setViewing(null); }}><section className="employee-modal detail-modal" role="dialog" aria-modal="true" aria-labelledby="detail-title"><div className="modal-heading"><div><span className="eyebrow"><span className="eyebrow-dot" /> EMPLOYEE PROFILE</span><h2 id="detail-title">{loadingDetails ? "Loading profile…" : viewing.name}</h2><p>{loadingDetails ? "Fetching the latest employee details." : viewing.position || "Team member"}</p></div><button className="modal-close" onClick={() => setViewing(null)} aria-label="Close dialog">×</button></div>{loadingDetails ? <div className="empty-state"><span className="spinner" /></div> : <div className="detail-grid"><div><span>Email</span><strong>{viewing.email}</strong></div><div><span>Phone</span><strong>{viewing.phone || "Not provided"}</strong></div><div><span>Department</span><strong>{viewing.department || "Unassigned"}</strong></div><div><span>Position</span><strong>{viewing.position || "Not provided"}</strong></div><div><span>Annual salary</span><strong>{currency(viewing.salary)}</strong></div></div>}<div className="modal-actions"><button type="button" className="cancel-button" onClick={() => setViewing(null)}>Close</button>{!loadingDetails && <button className="primary-button" onClick={() => { setViewing(null); openEdit(viewing); }}>Edit employee</button>}</div></section></div>}

      {modal && <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setModal(false); }}><section className="employee-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-heading"><div><span className="eyebrow"><span className="eyebrow-dot" /> TEAM DIRECTORY</span><h2 id="modal-title">{editing ? "Edit employee" : "Add a teammate"}</h2><p>{editing ? "Update this employee’s information." : "Add someone new to your organization."}</p></div><button className="modal-close" onClick={() => setModal(false)} aria-label="Close dialog">×</button></div><form onSubmit={submitEmployee}><div className="form-grid"><label className="form-field full-field">Full name <span>*</span><input autoFocus required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="e.g. Alex Morgan" /></label><label className="form-field">Email address <span>*</span><input type="email" required value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} placeholder="alex@company.com" /></label><label className="form-field">Phone number<input value={form.phone || ""} onChange={(event) => setForm({ ...form, phone: event.target.value })} placeholder="+1 (555) 000-0000" /></label><label className="form-field">Department<select value={form.department || ""} onChange={(event) => setForm({ ...form, department: event.target.value })}><option value="">Select department</option>{departments.map((item) => <option key={item}>{item}</option>)}</select></label><label className="form-field">Job title<input value={form.position || ""} onChange={(event) => setForm({ ...form, position: event.target.value })} placeholder="e.g. Product designer" /></label><label className="form-field full-field">Annual salary <span className="optional">(optional)</span><div className="salary-input"><span>$</span><input type="number" min="0" step="100" value={form.salary ?? ""} onChange={(event) => setForm({ ...form, salary: event.target.value })} placeholder="0.00" /></div></label></div>{error && <p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="cancel-button" onClick={() => setModal(false)}>Cancel</button><button className="primary-button" disabled={saving}>{saving ? "Saving..." : editing ? "Save changes" : "Add employee"}</button></div></form></section></div>}
    </main>
  );
}
